def moyenne(notes):
    total = 0
    for note in notes:
        total += note
    return total / len(notes)

print(moyenne([]))
→ ce programme provoque une erreur ZeroDivisionError, car len([]) vaut 0 et on ne peut pas diviser par 0 : c'est un cas limite (liste vide) que la fonction n'anticipe pas.

def calculer_moyenne(notes):
    if len(notes) == 0:
        return 0
    return sum(notes) / len(notes)

def evaluer(moyenne):
    if moyenne >= 10:
        return "admis"
    else:
        return "non admis"

notes = [12, 8, 15]
resultat = evaluer(calculer_moyenne(notes))
print(resultat)
→ calculer_moyenne renvoie (12+8+15)/3 = 11.67, puis evaluer(11.67) renvoie 'admis' car 11.67 >= 10 ; le programme affiche 'admis'.

4E.example:
def factorielle(n):
    if n == 0:
        return 1
    return n * factorielle(n - 1)

print(factorielle(4))
→ factorielle(4) = 4 * factorielle(3) = 4 * 3 * factorielle(2) = 4 * 3 * 2 * factorielle(1) = 4 * 3 * 2 * 1 * factorielle(0) = 4 * 3 * 2 * 1 * 1 = 24 ; le programme affiche 24.

class Personnage:
    def __init__(self, nom, points_de_vie):
        self.nom = nom
        self.points_de_vie = points_de_vie

    def subir_degats(self, degats):
        self.points_de_vie -= degats

heros = Personnage("Aria", 100)
heros.subir_degats(30)
print(heros.points_de_vie)
→ heros est un objet créé à partir de la classe Personnage, avec 100 points de vie au départ ; après subir_degats(30), points_de_vie devient 70, et le programme affiche 70.

