class CompteBancaire:
    def __init__(self, solde):
        self.solde = solde

    def retirer(self, montant):
        if montant > self.solde:
            return "Solde insuffisant"
        self.solde -= montant
        return "Retrait effectué"

compte = CompteBancaire(50)
print(compte.retirer(80))
print(compte.retirer(20))
→ le premier retrait de 80 échoue car 80 > 50, affiche 'Solde insuffisant' ; le deuxième retrait de 20 réussit (50 >= 20), affiche 'Retrait effectué', et compte.solde vaut alors 30.

3E.example:
def diviser(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "Erreur : division par zéro impossible"

print(diviser(10, 2))
print(diviser(10, 0))
→ diviser(10, 2) ne provoque pas d'erreur et renvoie 5.0 ; diviser(10, 0) déclenche l'exception ZeroDivisionError, interceptée par le except, qui renvoie le message d'erreur au lieu de faire planter le programme.

